double k=1/304.8;
var lvl=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name==Tama.Args.Get(args,"level",""));
var up=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name==Tama.Args.Get(args,"topLevel",""));
var view=new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>().First(v=>!v.IsTemplate&&v.GenLevel!=null&&v.GenLevel.Id==lvl.Id&&v.ViewType==ViewType.FloorPlan);
var sp=SketchPlane.Create(doc,lvl.Id);
var sepIds=new List<int>();
foreach(var o in args["seps"] as object[]){
 var a=o as object[];
 var ca=new CurveArray();
 ca.Append(Line.CreateBound(new XYZ(Convert.ToDouble(a[1])*k,Convert.ToDouble(a[2])*k,lvl.Elevation),new XYZ(Convert.ToDouble(a[3])*k,Convert.ToDouble(a[4])*k,lvl.Elevation)));
 var ms=doc.Create.NewRoomBoundaryLines(sp,ca,view);
 foreach(Element e in ms)sepIds.Add(e.Id.IntegerValue);
}
doc.Regenerate();
var made=new List<Autodesk.Revit.DB.Architecture.Room>();
var rep=new List<object>();
foreach(var o in args["rooms"] as object[]){
 var a=o as object[];
 double x=Convert.ToDouble(a[2]),y=Convert.ToDouble(a[3]);
 var r=doc.Create.NewRoom(lvl,new UV(x*k,y*k));
 if(r==null){rep.Add(new{src=a[4],err="null"});continue;}
 made.Add(r);
 r.get_Parameter(BuiltInParameter.ROOM_NAME).Set(Convert.ToString(a[1]));
 r.get_Parameter(BuiltInParameter.ROOM_NUMBER).Set(Convert.ToString(a[0]));
 r.get_Parameter(BuiltInParameter.ROOM_UPPER_LEVEL).Set(up.Id);
 r.get_Parameter(BuiltInParameter.ROOM_UPPER_OFFSET).Set(0.0);
 rep.Add(new{src=a[4],id=r.Id.IntegerValue,num=a[0],area=Math.Round(r.Area*0.09290304,2)});
}
doc.Regenerate();
var del=new List<object>();
foreach(var r in made){
 double ar=r.Area*0.09290304;
 if(ar<=0.0001){del.Add(new{num=r.Number,name=r.Name});doc.Delete(r.Id);}
}
return new{seps=sepIds,rooms=rep,deletedNotEnclosed=del};
